// 三、全量 23 只 + 便捷索引
// ============================================================
export const ALL_23_STOCKS: Stock[] = [...SAMPLING_10_STOCKS, ...EXTREME_SCENARIO_STOCKS]

export const getStockBySymbol = (symbol: string): Stock | undefined =>
  ALL_23_STOCKS.find((s) => s.symbol === symbol)

export const getStocksByGroup = (group: string): Stock[] =>
  ALL_23_STOCKS.filter((s) => s.group === group)

export default ALL_23_STOCKS
